// Usage-type prefix → region (APS3-NatGateway-Hours → ap-south-1)
const PFX = { USE1: 'us-east-1', USE2: 'us-east-2', USW1: 'us-west-1', USW2: 'us-west-2', CAN1: 'ca-central-1', SAE1: 'sa-east-1',
  EU: 'eu-west-1', EUW1: 'eu-west-1', EUW2: 'eu-west-2', EUW3: 'eu-west-3', EUC1: 'eu-central-1', EUC2: 'eu-central-2', EUN1: 'eu-north-1', EUS1: 'eu-south-1',
  APS1: 'ap-southeast-1', APS2: 'ap-southeast-2', APS3: 'ap-south-1', APS4: 'ap-southeast-3', APS5: 'ap-south-2',
  APN1: 'ap-northeast-1', APN2: 'ap-northeast-2', APN3: 'ap-northeast-3', APE1: 'ap-east-1', MES1: 'me-south-1', MEC1: 'me-central-1', AFS1: 'af-south-1' };
const flat = node => $(node).all().flatMap(i => i.json.ResultsByTime || []);
const series = [];
for (const day of flat('Get AWS Cost by Service & Region'))
  for (const g of day.Groups || []) {
    const cost = Number(g.Metrics?.UnblendedCost?.Amount || 0);
    if (Math.abs(cost) < 0.005) continue;
    series.push({ provider: 'aws', date: day.TimePeriod.Start, service: g.Keys[0], region: g.Keys[1] || 'global', cost, estimated: !!day.Estimated });
  }
const drivers = [];
for (const day of flat('Get AWS Cost by Usage Type'))
  for (const g of day.Groups || []) {
    const cost = Number(g.Metrics?.UnblendedCost?.Amount || 0);
    if (Math.abs(cost) < 0.005) continue;
    const ut = g.Keys[1] || '';
    const m = ut.match(/^([A-Z]{2,4}\d?)-/);
    const region = m && PFX[m[1]] ? PFX[m[1]] : (/^[A-Z]{2,4}\d-/.test(ut) ? 'unknown' : 'us-east-1');
    drivers.push({ provider: 'aws', date: day.TimePeriod.Start, service: g.Keys[0], region, driver: ut, cost });
  }
return [{ json: { series, drivers } }];

const res = $input.first().json;
const names = (res.schema?.fields || []).map(f => f.name);
const rows = (res.rows || []).map(r => Object.fromEntries(r.f.map((c, i) => [names[i], c.v])));
const agg = {};
const drivers = rows.map(r => {
  const k = `${r.d}|${r.service}|${r.region}`;
  agg[k] = (agg[k] || 0) + Number(r.cost);
  return { provider: 'gcp', date: r.d, service: r.service, region: r.region, driver: r.sku, cost: Number(r.cost) };
});
const series = Object.entries(agg).map(([k, cost]) => { const [date, service, region] = k.split('|');
  return { provider: 'gcp', date, service, region, cost, estimated: false }; });
return [{ json: { series, drivers, job_complete: res.jobComplete !== false } }];

const cfg = $('Set Cost Agent Config').first().json;
const series = [], drivers = [];
for (const n of ['Normalize AWS Costs', 'Normalize GCP Costs']) {
  if (!$(n).isExecuted) continue;
  const j = $(n).first().json; series.push(...(j.series || [])); drivers.push(...(j.drivers || []));
}
const log = $('Read Anomaly Log Sheet').all().map(i => i.json).filter(r => r.anomaly_key);
const seenKeys = new Set(log.map(r => r.anomaly_key));
const muted = new Set(log.filter(r => r.status === 'Ignored' && r.suppress_until && r.suppress_until >= cfg.today)
  .map(r => `${r.provider}|${r.service}|${r.region}`));

const dates = []; { let d = DateTime.fromISO(cfg.window_start, { zone: 'utc' }); const end = DateTime.fromISO(cfg.target_date, { zone: 'utc' });
  while (d <= end) { dates.push(d.toFormat('yyyy-LL-dd')); d = d.plus({ days: 1 }); } }
const grid = {};
series.forEach(s => { const k = `${s.provider}|${s.service}|${s.region}`; (grid[k] = grid[k] || {})[s.date] = ((grid[k] || {})[s.date] || 0) + s.cost; });
const r2 = x => Math.round(x * 100) / 100;
const hex = n => Array.from({ length: n }, () => Math.floor(Math.random() * 16).toString(16)).join('');

const totals = { cur: 0, prev: 0 };
const found = [];
for (const [k, byDate] of Object.entries(grid)) {
  const [provider, service, region] = k.split('|');
  const cur = byDate[cfg.target_date] || 0, prev = byDate[cfg.prev_date] || 0;
  totals.cur += cur; totals.prev += prev;
  const hist = dates.slice(-9, -2).map(d => byDate[d] || 0);            // 7 days before prev_date
  const mean = hist.reduce((a, b) => a + b, 0) / hist.length;
  const sd = Math.sqrt(hist.reduce((a, b) => a + (b - mean) ** 2, 0) / Math.max(hist.length - 1, 1));
  const z = (cur - mean) / Math.max(sd, mean * 0.05, 1);
  const dAbs = cur - prev, dPct = prev > 0 ? dAbs / prev : (cur > 0 ? 9.99 : 0);
  const up = dAbs >= cfg.min_abs_usd && (dPct >= cfg.min_pct || z >= cfg.z_threshold);
  const down = cfg.alert_on_drops && -dAbs >= cfg.min_abs_usd && dPct <= -cfg.min_pct;
  if (!up && !down) continue;
  const key = `${cfg.target_date}|${k}`;
  if (seenKeys.has(key) || muted.has(k)) continue;
  const dDelta = {};
  drivers.filter(x => x.provider === provider && x.service === service && (provider === 'gcp' ? x.region === region : (x.region === region || region === 'global' || region === 'NoRegion')))
    .forEach(x => { const o = dDelta[x.driver] = dDelta[x.driver] || { cur: 0, prev: 0 };
      if (x.date === cfg.target_date) o.cur += x.cost; else if (x.date === cfg.prev_date) o.prev += x.cost; });
  const top = Object.entries(dDelta).map(([driver, v]) => ({ driver, cur: r2(v.cur), prev: r2(v.prev), delta: r2(v.cur - v.prev) }))
    .filter(d => Math.abs(d.delta) >= 0.5).sort((a, b) => b.delta - a.delta).slice(0, 6);
  found.push({ anomaly_id: hex(10), token: hex(24), anomaly_key: key, provider, service, region,
    target_date: cfg.target_date, prev_date: cfg.prev_date,
    kind: down ? 'drop' : (prev < 1 && mean < 1 ? 'new_spend' : 'spike'),
    cost_yesterday: r2(cur), cost_prev_day: r2(prev), avg_7d: r2(mean), dod_abs: r2(dAbs),
    dod_pct: Math.round(dPct * 1000) / 10, z_score: Math.round(z * 10) / 10,
    monthly_impact: r2(dAbs * 30), estimated: series.some(s => s.date === cfg.target_date && s.estimated),
    severity: Math.abs(dAbs) >= 500 ? 'Critical' : Math.abs(dAbs) >= 100 ? 'High' : 'Medium',
    drivers: top, history_14d: dates.map(d => r2(byDate[d] || 0)),
    cloudtrail_region: provider === 'aws' && /^[a-z]{2}-[a-z]+-\d$/.test(region) ? region : null });
}
found.sort((a, b) => Math.abs(b.dod_abs) - Math.abs(a.dod_abs));
const sel = found.slice(0, cfg.max_alerts_per_run);
return sel.map((a, i) => ({ json: { ...a, rank: i + 1, total_anomalies: found.length,
  account_total_yesterday: r2(totals.cur), account_total_prev: r2(totals.prev) } }));

const items = $input.all().map(i => i.json);
const first = $('Detect Day-over-Day Anomalies').all().map(i => i.json);
if (first.length < 2) return [];
const total = first.reduce((a, x) => a + x.dod_abs, 0);
const more = first[0].total_anomalies - first.length;
return [{ json: { text: `:bar_chart: *Cost anomaly run – ${first[0].target_date}*\n${first.length} anomalies alerted` +
  `${more > 0 ? ` (+${more} more under the per-run cap)` : ''} · combined DoD change *$${total.toFixed(2)}* (~$${(total * 30).toFixed(0)}/month if sustained)\n` +
  first.map(a => `• ${a.severity} · ${a.provider.toUpperCase()} ${a.service} (${a.region}): +$${a.dod_abs}`).join('\n') } }];

const a = $('Loop Over Anomalies').first().json;
const r = $input.first().json || {};
const MUT = /^(Create|Run|Allocate|Start|Modify|Put|Attach|Associate|Update|Enable|Register|Request|Launch|Scale|Set)/;
const events = (Array.isArray(r.body?.Events) ? r.body.Events : [])
  .filter(e => MUT.test(e.EventName || ''))
  .map(e => ({ time: new Date(e.EventTime * 1000 || e.EventTime).toISOString().slice(0, 16), event: e.EventName,
    source: String(e.EventSource || '').replace('.amazonaws.com', ''), user: e.Username || '',
    resources: (e.Resources || []).map(x => `${x.ResourceType}:${x.ResourceName}`).slice(0, 3).join(', ') }))
  .slice(0, 25);
return [{ json: { ...a, cloudtrail_events: events, cloudtrail_checked: !!a.cloudtrail_region,
  cloudtrail_error: r.statusCode && r.statusCode >= 300 ? `HTTP ${r.statusCode}` : '' } }];

const a = $('Build AI Context').first().json;
const ai = $input.first().json.message?.content || {};
const cfg = $('Set Cost Agent Config').first().json;
const money = v => `$${Number(v).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
const link = act => `${cfg.webhook_base_url}/webhook/cost-anomaly-action?id=${a.anomaly_id}&t=${a.token}&a=${act}`;
const sev = { Critical: ':rotating_light:', High: ':red_circle:', Medium: ':large_orange_circle:' }[a.severity];
const consoleUrl = a.provider === 'aws' ? cfg.aws_console_url : cfg.gcp_console_url;
const blocks = [
  { type: 'header', text: { type: 'plain_text', text: `${a.kind === 'drop' ? '📉' : '💸'} Cost anomaly · ${a.provider.toUpperCase()} · ${a.service}`.slice(0, 150) } },
  { type: 'section', text: { type: 'mrkdwn', text: `${sev} *${ai.headline || 'Unexplained cost change'}*\n_${a.region} · ${a.target_date}${a.estimated ? ' · provisional data' : ''}_` } },
  { type: 'section', fields: [
    { type: 'mrkdwn', text: `*Yesterday*\n${money(a.cost_yesterday)}` },
    { type: 'mrkdwn', text: `*Day before*\n${money(a.cost_prev_day)} (${a.dod_abs >= 0 ? '+' : ''}${a.dod_pct}%)` },
    { type: 'mrkdwn', text: `*7-day avg / z-score*\n${money(a.avg_7d)} / ${a.z_score}` },
    { type: 'mrkdwn', text: `*If sustained*\n~${money(a.monthly_impact)}/month` } ] },
  { type: 'section', text: { type: 'mrkdwn', text: `*Probable cause* (${ai.confidence || '?'} confidence): ${ai.probable_cause || '-'}\n` +
      (ai.evidence || []).map(e => `• ${e}`).join('\n') } },
  ...(a.drivers.length ? [{ type: 'context', elements: [{ type: 'mrkdwn', text: '*Top drivers:* ' +
      a.drivers.slice(0, 4).map(d => `\`${d.driver}\` ${d.delta >= 0 ? '+' : ''}${money(d.delta)}`).join(' · ') }] }] : []),
  ...((ai.recommended_actions || []).length ? [{ type: 'section', text: { type: 'mrkdwn', text: '*Suggested actions*\n' +
      ai.recommended_actions.map((x, i) => `${i + 1}. ${x}`).join('\n') } }] : []),
  { type: 'actions', elements: [
    { type: 'button', style: 'primary', text: { type: 'plain_text', text: '✅ Approve (expected)' }, url: link('approve') },
    { type: 'button', style: 'danger', text: { type: 'plain_text', text: `🙈 Ignore ${cfg.ignore_days}d` }, url: link('ignore') },
    { type: 'button', text: { type: 'plain_text', text: '🔎 Open billing console' }, url: consoleUrl } ] },
  { type: 'context', elements: [{ type: 'mrkdwn', text: `Anomaly ${a.rank}/${a.total_anomalies} · id \`${a.anomaly_id}\` · account total ${money(a.account_total_yesterday)} vs ${money(a.account_total_prev)}` }] }
];
return [{ json: { ...a, ai_headline: ai.headline || '', ai_cause: ai.probable_cause || '', ai_confidence: ai.confidence || '',
  likely_intentional: ai.likely_intentional ? 'Yes' : 'No', slack_blocks: blocks,
  fallback: `Cost anomaly ${a.provider}/${a.service}/${a.region}: ${money(a.cost_prev_day)} → ${money(a.cost_yesterday)}` } }];

const q = $('On Approve or Ignore Link Click').first().json.query || {};
const a = $input.first()?.json || {};
const action = String(q.a || '').toLowerCase();
let reason = '';
if (!a.anomaly_id) reason = 'Anomaly not found';
else if (!a.token || a.token === 'used' || q.t !== a.token) reason = 'This link is invalid or was already used';
else if (!['approve', 'ignore'].includes(action)) reason = 'Unknown action';
const until = action === 'ignore' ? $now.setZone('Asia/Kolkata').plus({ days: 7 }).toFormat('yyyy-LL-dd') : '';
return [{ json: { ...a, action, valid: !reason, reason, suppress_until: until,
  new_status: action === 'approve' ? 'Approved' : 'Ignored', decided_at: $now.toISO() } }];
